import test from "node:test";
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { json, loadPlugin, profileResponse, savedSession, siteHandler } from "./helpers.mjs";

const CALLBACKS = ["account", "browse", "home", "played", "recent", "search", "show", "signIn", "signOut", "stream"].sort();

test("bundle: single file with the full MyGo callback contract", async () => {
  const source = await readFile(new URL("../index.js", import.meta.url), "utf8");
  assert.ok(source.startsWith("// SPDX-License-Identifier: MIT"));
  assert.ok(source.includes("Generated by npm run build"));
  assert.ok(!/^import\s/m.test(source), "bundle must not contain import statements");
  assert.ok(!/\brequire\(/.test(source), "bundle must not require Node modules");
  assert.ok(/^export \{ /m.test(source));
  const { plugin } = await loadPlugin(siteHandler());
  assert.deepEqual(Object.keys(plugin).sort(), CALLBACKS);
  for (const name of CALLBACKS) assert.equal(typeof plugin[name], "function", `${name} must be a function`);
});

test("account: anonymous by default, Safari UA, no cookie on CDN handoff", async () => {
  const { plugin, requests } = await loadPlugin(siteHandler());
  assert.equal(await plugin.account(), null);
  const found = await plugin.search({ query: "唐诗", kind: "tracks" });
  assert.equal(found.tracks[0].id, "1001");
  assert.ok(requests.length > 0);
  const first = requests[0];
  assert.equal(first.url.origin, "https://www.ximalaya.com");
  assert.match(first.init.headers["User-Agent"], /Safari\/605\.1\.15/);
  assert.equal(first.init.headers.Referer, "https://www.ximalaya.com/");
  assert.equal(first.init.headers.Cookie, undefined);
});

test("search: keywords, official links, shorthand ids and paging", async () => {
  const { plugin, requests } = await loadPlugin(siteHandler());
  const shows = await plugin.search({ query: "唐诗", kind: "shows" });
  assert.equal(shows.shows[0].id, "55");
  assert.equal(shows.shows[0].name, "搜索专辑");
  const tracks = await plugin.search({ query: "唐诗", kind: "tracks" });
  assert.equal(tracks.tracks[0].id, "1001");
  assert.equal(tracks.tracks[0].url, "https://www.ximalaya.com/sound/1001");
  const byAlbumLink = await plugin.search({ query: "https://www.ximalaya.com/album/55", kind: "tracks" });
  assert.equal(byAlbumLink.tracks.length, 30, "an album link must expand into episodes on the Songs tab");
  const bySoundLink = await plugin.search({ query: "https://www.ximalaya.com/sound/1001", kind: "tracks" });
  assert.equal(bySoundLink.tracks[0].id, "1001");
  const byShort = await plugin.search({ query: "album:55", kind: "shows" });
  assert.equal(byShort.shows[0].id, "55");
  const empty = await plugin.search({ query: "", kind: "tracks" });
  assert.deepEqual(empty, { tracks: [], more: false });
  assert.equal(requests.filter((call) => call.url.searchParams.get("page") === "2").length, 0);
  await assert.rejects(() => plugin.search({ query: "x", kind: "videos" }), /支持搜索声音和节目专辑/);
});

test("show: two pages are disjoint and browsing history is kept locally", async () => {
  const { plugin, storage } = await loadPlugin(siteHandler());
  const first = await plugin.show({ id: "55", offset: 0 });
  const second = await plugin.show({ id: "55", offset: first.episodes.length });
  assert.equal(first.show.name, "测试专辑");
  assert.equal(first.episodes.length, 30);
  assert.equal(second.episodes.length, 30);
  assert.equal(new Set([...first.episodes, ...second.episodes].map((track) => track.id)).size, 60);
  assert.equal(storage.get("viewedShows")[0].id, "55");
});

test("home: assembles sections and survives a failing endpoint", async () => {
  const { plugin } = await loadPlugin(siteHandler());
  const page = await plugin.home();
  assert.equal(page.title, "喜马拉雅");
  const titles = page.sections.map((section) => section.title);
  assert.ok(titles.includes("发现专辑") && titles.includes("榜单精选") && titles.includes("按分类浏览") && titles.includes("热门搜索"));
  assert.ok(page.sections[0].shows.length > 0);

  const failing = await loadPlugin(siteHandler({ "/revision/explore/guessYouLike": () => { throw new Error("boom"); } }));
  const degraded = await failing.plugin.home();
  assert.equal(degraded.sections[0].shows.length, 0);
  assert.match(degraded.sections[0].empty, /推荐暂不可用/);
  assert.ok(degraded.sections.some((section) => section.title === "榜单精选"));
});

test("browse: rankings, categories, hot-word search, local records", async () => {
  const { plugin } = await loadPlugin(siteHandler());
  const rank = await plugin.browse({ page: "rank" });
  assert.equal(rank.sections.length, 2);
  assert.ok(rank.sections.every((section) => section.shows.length === 1));
  const categories = await plugin.browse({ page: "categories" });
  assert.deepEqual(categories.sections[0].links.slice(0, 3).map((link) => link.page), ["category:0", "category:2", "category:3"]);
  const category = await plugin.browse({ page: "category:2" });
  assert.equal(category.sections[0].shows[0].id, "71");
  assert.equal(category.sections[0].morePage, "category:2:2");
  const hot = await plugin.browse({ page: `search:${encodeURIComponent("相声")}` });
  assert.equal(hot.title, "搜索 · 相声");
  assert.ok(hot.sections[0].tracks.length > 0);
  await plugin.played({ id: "1001" });
  const local = await plugin.browse({ page: "local-recent" });
  assert.equal(local.sections[0].tracks[0].id, "1001");
  await assert.rejects(() => plugin.browse({ page: "no-such-page" }), /没有这个喜马拉雅页面/);
});

test("account pages: subscriptions, purchases, cloud history and local records", async () => {
  const { plugin } = await loadPlugin(siteHandler(), savedSession());
  const profile = await plugin.account();
  assert.equal(profile.id, "42");
  assert.equal(profile.page, "account");
  const accountPage = await plugin.browse({ page: "account" });
  assert.equal(accountPage.title, "测试用户");
  const subscriptions = await plugin.browse({ page: "subscriptions" });
  assert.equal(subscriptions.sections[0].shows[0].id, "81");
  const purchases = await plugin.browse({ page: "purchases" });
  assert.equal(purchases.sections[0].shows[0].id, "82");
  const history = await plugin.browse({ page: "recent" });
  assert.equal(history.sections[0].title, "今天");
  assert.equal(history.sections[0].tracks[0].id, "1001");
  assert.equal(history.sections[0].tracks[0].description, "上次听到 1:05");
  assert.deepEqual(await plugin.recent(), history.sections[0].tracks);
});

test("stream: quality validation, decryption, mismatch detection, de-duplication", async () => {
  const { plugin, requests } = await loadPlugin(siteHandler());
  await assert.rejects(() => plugin.stream({ id: "1001", quality: "bogus" }), /不支持的音质选项/);
  const [first, second] = await Promise.all([plugin.stream({ id: "1001" }), plugin.stream({ id: "1001" })]);
  assert.deepEqual(first, second);
  assert.equal(first.type, "m4a");
  assert.match(first.url, /^https:\/\/a\.xmcdn\.com\//);
  assert.equal(requests.filter((call) => call.url.pathname.startsWith("/mobile-playpage")).length, 1, "concurrent streams must share one request");
  assert.equal(requests[0].url.searchParams.get("device"), "web");

  const mismatch = await loadPlugin((call) => {
    if (call.url.pathname.startsWith("/mobile-playpage/track/v3/baseInfo/")) {
      return json({ ret: 0, trackInfo: { trackId: 999, isAuthorized: true, playUrlList: [] } });
    }
    return siteHandler()(call);
  });
  await assert.rejects(() => mismatch.plugin.stream({ id: "1001" }), /喜马拉雅返回的单集不匹配/);
});

test("client: business codes, HTTP and network failures", async () => {
  const risk = await loadPlugin(siteHandler({ "/revision/search/seo": () => json({ ret: 1001, msg: "系统繁忙" }) }));
  await assert.rejects(() => risk.plugin.search({ query: "x" }), /要求验证访问/);
  const removed = await loadPlugin(siteHandler({ "/revision/search/seo": () => json({ ret: 929, msg: "下架" }) }));
  await assert.rejects(() => removed.plugin.search({ query: "x" }), /内容不存在或已下架/);
  const http = await loadPlugin(siteHandler({ "/revision/search/seo": () => json({}, {}, 500) }));
  await assert.rejects(() => http.plugin.search({ query: "x" }), /HTTP 500/);
  const offline = await loadPlugin(() => { throw new Error("network down"); });
  await assert.rejects(() => offline.plugin.search({ query: "x" }), /无法连接喜马拉雅/);
  const loginGone = await loadPlugin(siteHandler({ "/revision/search/seo": () => json({ ret: 200, isNeedLogin: true }) }), savedSession());
  await assert.rejects(() => loginGone.plugin.search({ query: "x" }), /登录状态已失效/);
  assert.equal(loginGone.storage.get("session"), undefined, "expired session must be removed");
});

test("client: only Ximalaya-domain cookies are absorbed", async () => {
  const withCookies = (call) => {
    if (call.url.pathname !== "/revision/search/seo") return siteHandler()(call);
    const headers = new Headers({ "Content-Type": "application/json" });
    headers.append("Set-Cookie", "evil=1; Domain=evil.com; Path=/");
    headers.append("Set-Cookie", "good=2; Domain=ximalaya.com; Path=/");
    headers.append("Set-Cookie", "scoped=3; Domain=ximalaya.com; Path=/private");
    return new Response(JSON.stringify({ ret: 200, data: { illegal: false, track: { docs: [], total: 0 } } }), { status: 200, headers });
  };
  const { plugin, storage } = await loadPlugin(withCookies, savedSession());
  await plugin.search({ query: "x", kind: "tracks" });
  const saved = storage.get("session").cookie;
  assert.match(saved, /good=2/);
  assert.doesNotMatch(saved, /evil=1/);
  assert.doesNotMatch(saved, /scoped=3/);
});

test("signIn: web window, profile, session persistence and concurrency guard", async () => {
  const { plugin, storage, prompts } = await loadPlugin(siteHandler());
  const profile = await plugin.signIn();
  assert.equal(profile.id, "42");
  assert.match(storage.get("session").cookie, /1&_token=synthetic-login/);
  assert.equal(prompts.at(-1).text, "登录成功");
  assert.equal((await plugin.account()).id, "42");
  plugin.signOut();
  assert.equal(await plugin.account(), null);
  assert.equal(storage.get("session"), undefined);

  const missing = await loadPlugin(siteHandler());
  delete missing.host.webSignIn;
  await assert.rejects(() => missing.plugin.signIn(), /请更新 MyGo Music/);

  let reference;
  const concurrent = await loadPlugin((call) => {
    if (call.url.pathname === "/revision/main/getCurrentUser") {
      reference.plugin.signOut();
      return profileResponse();
    }
    return siteHandler()(call);
  });
  reference = { plugin: concurrent.plugin };
  await assert.rejects(() => concurrent.plugin.signIn(), /账号状态已改变/);
});

test("stream: lossless falls back to high when the service has no FLAC", async () => {
  const { plugin } = await loadPlugin(siteHandler());
  const result = await plugin.stream({ id: "1001", quality: "lossless" });
  assert.equal(result.quality, "high");
  assert.equal(result.type, "m4a");
  assert.equal(result.fallbackFrom, "lossless");
  assert.match(result.url, /^https:\/\/a\.xmcdn\.com\//);
});
